  });
  await page.reload();
  await page.waitForTimeout(500);
  await page.locator('#start-button').click();
  const advanceDialogue = async () => {
    for (let i=0;i<5 && await page.locator('#dialogue-next').isVisible();i++) await page.locator('#dialogue-next').click();
  };
